#include <vector>
#include <numeric>
#include <algorithm>

using namespace std;

class Solution {
public:
    long long maxWeight(vector<int>& pizzas) {
        sort(pizzas.rbegin(), pizzas.rend());
        int totalDays = pizzas.size() / 4;
        int oddDays = (totalDays + 1) / 2;
        int evenDays = totalDays / 2;
        long long ans = 0;
        for (int i = 0; i < oddDays; i++) {
            ans += pizzas[i];
        }
        int idx = oddDays;
        for (int i = 0; i < evenDays; i++) {
            idx++;
            ans += pizzas[idx];
            idx++;
        }
        return ans;
    }
};

import java.util.Arrays;

class Solution {
    public long maxWeight(int[] pizzas) {
        Arrays.sort(pizzas);
        int n = pizzas.length;
        int totalDays = n / 4;
        int oddDays = (totalDays + 1) / 2;
        int evenDays = totalDays / 2;
        long ans = 0;
        int r = n - 1;
        for (int i = 0; i < oddDays; i++) {
            ans += pizzas[r--];
        }
        for (int i = 0; i < evenDays; i++) {
            r--;
            ans += pizzas[r--];
        }
        return ans;
    }
}

/**
 * @param {number[]} pizzas
 * @return {number}
 */
var maxWeight = function(pizzas) {
    pizzas.sort((a, b) => b - a);
    const totalDays = Math.floor(pizzas.length / 4);
    const oddDays = Math.floor((totalDays + 1) / 2);
    const evenDays = Math.floor(totalDays / 2);
    let ans = 0;
    for (let i = 0; i < oddDays; i++) {
        ans += pizzas[i];
    }
    let idx = oddDays;
    for (let i = 0; i < evenDays; i++) {
        idx++;
        ans += pizzas[idx];
        idx++;
    }
    return ans;
};
